use crate::types::Settings;use crate::{CoreError,Result};use serde_json::Value;use std::fs;use std::path::{Path,PathBuf};
#[derive(Debug,Clone)]pub struct SettingsStore{path:PathBuf}impl SettingsStore{pub fn new(path:impl Into<PathBuf>)->Self{Self{path:path.into()}}pub fn load(&self)->Result<Settings>{if !self.path.exists(){return Ok(Settings::default())}let s:Settings=serde_json::from_slice(&fs::read(&self.path)?)?;s.validate().map_err(|m|CoreError::InvalidSetting{key:"settings".into(),message:m})?;Ok(s)}pub fn save(&self,s:&Settings)->Result<()>{s.validate().map_err(|m|CoreError::InvalidSetting{key:"settings".into(),message:m})?;write_json(&self.path,s)}pub fn update(&self,key:&str,value:Value)->Result<Settings>{let mut json=serde_json::to_value(self.load()?)?;let object=json.as_object_mut().ok_or_else(||CoreError::InvalidValue("settings object expected".into()))?;if !object.contains_key(key){return Err(CoreError::InvalidSetting{key:key.into(),message:"unknown setting".into()})}object.insert(key.into(),value);let s:Settings=serde_json::from_value(json)?;self.save(&s)?;Ok(s)}}
pub(crate)fn write_json<T:serde::Serialize>(path:&Path,value:&T)->Result<()>{if let Some(p)=path.parent().filter(|p|!p.as_os_str().is_empty()){fs::create_dir_all(p)?}let tmp=path.with_file_name(format!(".{}.tmp",path.file_name().and_then(|n|n.to_str()).unwrap_or("data")));fs::write(&tmp,serde_json::to_vec_pretty(value)?)?;if let Err(e)=fs::rename(&tmp,path){let _=fs::remove_file(tmp);return Err(e.into())}Ok(())}
